import type { MatchRecord, StoredPlayer } from "@/types/match";

// Statistics and "things to improve" computed in code from the user's own saved matches.
// Nothing here is generated by an AI model and nothing is fabricated: with too few matches we say so.
// Pure and deterministic: nothing in this file mutates its input. (Single file on purpose: the node:test runner used by
// tests/ cannot resolve extension-less relative imports.)

export const MIN_GAMES_FOR_INSIGHTS = 3;
/** A hero needs this many games before its win rate is called out as good/bad (or ranked in the hero table). */
export const MIN_HERO_GAMES = 5;
/** Below this many games every observation carries a "small sample" note. */
export const SMALL_SAMPLE = 10;
const WINDOW = 20; // default insight window (latest 20 matches); pass another limit to override

export interface Summary {
  games: number;
  wins: number;
  winRate: number; // 0-1
  avgKills: number;
  avgDeaths: number;
  avgAssists: number;
  kda: number;
  avgGold: number;
  avgRating: number;
  mvpCount: number;
}

// Non-finite values (NaN / Infinity from a bad row) are skipped instead of poisoning the average.
const mean = (xs: number[]) => {
  const v = xs.filter(Number.isFinite);
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : 0;
};
export const kdaOf = (k: number, d: number, a: number) => (k + a) / Math.max(d, 1);

/** Grouping key for "which hero": the hero id when known, else the lower-cased name. */
export const heroKey = (m: MatchRecord) => m.myHeroId ?? `name:${m.myHeroName.toLowerCase()}`;

export function summarize(ms: MatchRecord[]): Summary | null {
  if (ms.length === 0) return null;
  const wins = ms.filter((m) => m.result === "victory").length;
  const k = mean(ms.map((m) => m.kills));
  const d = mean(ms.map((m) => m.deaths));
  const a = mean(ms.map((m) => m.assists));
  return {
    games: ms.length,
    wins,
    winRate: wins / ms.length,
    avgKills: k,
    avgDeaths: d,
    avgAssists: a,
    kda: kdaOf(k, d, a),
    avgGold: mean(ms.map((m) => m.gold)),
    avgRating: mean(ms.map((m) => m.rating)),
    mvpCount: ms.filter((m) => m.mvp).length,
  };
}

export interface HeroLine {
  key: string;
  heroId: string | null;
  heroName: string;
  games: number;
  wins: number;
  winRate: number;
  kda: number;
}

export function byHero(ms: MatchRecord[]): HeroLine[] {
  const groups = new Map<string, MatchRecord[]>();
  for (const m of ms) {
    const key = heroKey(m);
    groups.set(key, [...(groups.get(key) ?? []), m]);
  }
  return [...groups.entries()]
    .map(([key, g]) => {
      const wins = g.filter((m) => m.result === "victory").length;
      return {
        key,
        heroId: g[0].myHeroId,
        heroName: g[0].myHeroName,
        games: g.length,
        wins,
        winRate: wins / g.length,
        kda: kdaOf(mean(g.map((m) => m.kills)), mean(g.map((m) => m.deaths)), mean(g.map((m) => m.assists))),
      };
    })
    .sort((a, b) => b.games - a.games || b.winRate - a.winRate);
}

export interface Insight {
  id: string;
  tone: "good" | "warn";
  title: string;
  /** What the numbers say (measurable). */
  detail: string;
  /** What the player could try (advice, not a measurement). */
  suggestion?: string;
}

const mates = (m: MatchRecord): StoredPlayer[] => m.players.filter((p) => p.team === m.myTeam && !p.isMe);

/**
 * `all` must be newest first and ALREADY filtered by the caller (time range / hero); `limit` caps how many of the newest
 * matches are looked at. Gold and rating are compared with teammates in the same screenshot: context, not a skill score.
 */
export function buildInsights(all: MatchRecord[], limit: number = WINDOW): Insight[] {
  if (all.length < MIN_GAMES_FOR_INSIGHTS) return [];
  const ms = all.slice(0, limit).filter((m) => mates(m).length > 0);
  if (ms.length < MIN_GAMES_FOR_INSIGHTS) return [];
  const n = ms.length;
  const small = n < SMALL_SAMPLE ? " (ตัวอย่างยังน้อย ผลอาจเปลี่ยนได้เมื่อมีแมตช์เพิ่ม)" : "";
  const out: Insight[] = [];

  // 1) Deaths vs teammates
  const myDeaths = mean(ms.map((m) => m.deaths));
  const mateDeaths = mean(ms.map((m) => mean(mates(m).map((p) => p.deaths))));
  if (myDeaths - mateDeaths >= 1 && myDeaths >= mateDeaths * 1.25) {
    out.push({
      id: "deaths-high",
      tone: "warn",
      title: "ตายมากกว่าเพื่อนร่วมทีม",
      detail: `เฉลี่ย ${myDeaths.toFixed(1)} ครั้ง/เกม เทียบกับเพื่อนร่วมทีม ${mateDeaths.toFixed(1)} ครั้ง (${n} แมตช์)${small}`,
      suggestion: "ลองถอยตั้งหลักเร็วขึ้นเมื่อเสียเปรียบ",
    });
  } else if (mateDeaths - myDeaths >= 1 && myDeaths <= mateDeaths * 0.75) {
    out.push({
      id: "deaths-low",
      tone: "good",
      title: "ตายน้อยกว่าเพื่อนร่วมทีม",
      detail: `เฉลี่ย ${myDeaths.toFixed(1)} ครั้ง/เกม เทียบกับเพื่อนร่วมทีม ${mateDeaths.toFixed(1)} ครั้ง (${n} แมตช์)${small}`,
    });
  }

  // 2) Gold vs teammates (role matters: roaming usually earns less gold)
  const myGold = mean(ms.map((m) => m.gold));
  const mateGold = mean(ms.map((m) => mean(mates(m).map((p) => p.gold))));
  if (mateGold > 0) {
    const ratio = myGold / mateGold;
    if (ratio < 0.9) {
      out.push({
        id: "gold-low",
        tone: "warn",
        title: "ทองต่ำกว่าเพื่อนร่วมทีม",
        detail: `ได้ทองเฉลี่ย ${Math.round(ratio * 100)}% ของเพื่อนร่วมทีม (${n} แมตช์) ขึ้นกับบทบาท เช่น Roaming มักได้ทองน้อยกว่าอยู่แล้ว${small}`,
        suggestion: "ถ้าเล่นบทบาทที่ควรฟาร์ม ลองเก็บมินเนียนและมอนสเตอร์ให้ครบขึ้น",
      });
    } else if (ratio >= 1.1) {
      out.push({
        id: "gold-high",
        tone: "good",
        title: "ฟาร์มทองได้ดีกว่าเพื่อนร่วมทีม",
        detail: `ได้ทองเฉลี่ย ${Math.round(ratio * 100)}% ของเพื่อนร่วมทีม (${n} แมตช์)${small}`,
      });
    }
  }

  // 3) Kill participation = (kills + assists) / team kills.
  // Rows where K+A exceeds the printed team score (misread OCR / edited by hand) are skipped, not clamped to 100%.
  const kps = ms
    .map((m) => ({ tk: m.myTeam === "blue" ? m.scoreBlue : m.scoreRed, ka: m.kills + m.assists }))
    .filter((x) => Number.isFinite(x.tk) && Number.isFinite(x.ka) && x.tk > 0 && x.ka <= x.tk)
    .map((x) => x.ka / x.tk);
  if (kps.length >= MIN_GAMES_FOR_INSIGHTS) {
    const kp = mean(kps);
    const kpSmall = kps.length < SMALL_SAMPLE ? " (ตัวอย่างยังน้อย)" : "";
    if (kp < 0.45) {
      out.push({
        id: "kp-low",
        tone: "warn",
        title: "เข้าร่วมการสู้น้อย",
        detail: `มีส่วนร่วมใน ${Math.round(kp * 100)}% ของ Kill ทีม (${kps.length} แมตช์ที่ข้อมูลสอดคล้องกัน)${kpSmall}`,
        suggestion: "ลองเข้าร่วมการสู้ของทีมให้บ่อยขึ้น",
      });
    } else if (kp >= 0.65) {
      out.push({
        id: "kp-high",
        tone: "good",
        title: "เข้าร่วมการสู้สม่ำเสมอ",
        detail: `มีส่วนร่วมใน ${Math.round(kp * 100)}% ของ Kill ทีม (${kps.length} แมตช์ที่ข้อมูลสอดคล้องกัน)${kpSmall}`,
      });
    }
  }

  // 4) Rating vs teammates
  const myRating = mean(ms.map((m) => m.rating));
  const mateRating = mean(ms.map((m) => mean(mates(m).map((p) => p.rating))));
  if (myRating - mateRating <= -1) {
    out.push({
      id: "rating-low",
      tone: "warn",
      title: "คะแนนเฉลี่ยต่ำกว่าเพื่อนร่วมทีม",
      detail: `${myRating.toFixed(1)} เทียบกับเพื่อนร่วมทีม ${mateRating.toFixed(1)} (${n} แมตช์) คะแนนในเกมเป็นเพียงตัวชี้วัดประกอบ${small}`,
    });
  } else if (myRating - mateRating >= 1) {
    out.push({
      id: "rating-high",
      tone: "good",
      title: "คะแนนเฉลี่ยสูงกว่าเพื่อนร่วมทีม",
      detail: `${myRating.toFixed(1)} เทียบกับเพื่อนร่วมทีม ${mateRating.toFixed(1)} (${n} แมตช์) คะแนนในเกมเป็นเพียงตัวชี้วัดประกอบ${small}`,
    });
  }

  // 5) Hero win rate (needs MIN_HERO_GAMES+ games on that hero)
  const heroes = byHero(ms).filter((h) => h.games >= MIN_HERO_GAMES);
  const worst = [...heroes].sort((a, b) => a.winRate - b.winRate)[0];
  const best = [...heroes].sort((a, b) => b.winRate - a.winRate)[0];
  if (worst && worst.winRate <= 0.35) {
    out.push({
      id: "hero-worst",
      tone: "warn",
      title: `${worst.heroName} ชนะน้อย`,
      detail: `ชนะ ${worst.wins} จาก ${worst.games} เกม`,
      suggestion: "ลองทบทวนการเล่นตัวนี้ หรือเลือกตัวที่ถนัดกว่า",
    });
  }
  if (best && best.winRate >= 0.65 && best !== worst) {
    out.push({
      id: "hero-best",
      tone: "good",
      title: `${best.heroName} คือตัวที่ชนะบ่อย`,
      detail: `ชนะ ${best.wins} จาก ${best.games} เกม`,
    });
  }

  return [...out.filter((i) => i.tone === "warn"), ...out.filter((i) => i.tone === "good")].slice(0, 4);
}

// ---- Filters ---------------------------------------------------------------------------------------------------------

export type RangePreset = "all" | "last10" | "last20" | "days7" | "days30";
export interface Filters {
  range: RangePreset;
  heroKey: string | null;
}
export const DEFAULT_FILTERS: Filters = { range: "all", heroKey: null };

const DAY_MS = 86_400_000;

/** Newest first by the scoreboard's printed time (same ordering as listMyMatches). Returns a copy. */
export const newestFirst = (ms: MatchRecord[]) => [...ms].sort((a, b) => b.playedAt.localeCompare(a.playedAt));

const timeOf = (m: MatchRecord) => {
  const t = new Date(m.playedAt).getTime(); // "YYYY-MM-DDTHH:mm:ss" without offset = local wall-clock time
  return Number.isFinite(t) ? t : null;
};

/**
 * Hero filter first, then the range. So "last 10" + a hero means that hero's last 10 games, not "heroes among the last 10".
 * Matches with an unreadable date are excluded from day-based ranges (never guessed).
 */
export function applyFilters(all: MatchRecord[], f: Filters, now: number = Date.now()): MatchRecord[] {
  let out = newestFirst(all);
  if (f.heroKey) out = out.filter((m) => heroKey(m) === f.heroKey);
  switch (f.range) {
    case "last10":
      return out.slice(0, 10);
    case "last20":
      return out.slice(0, 20);
    case "days7":
    case "days30": {
      const cutoff = now - (f.range === "days7" ? 7 : 30) * DAY_MS;
      return out.filter((m) => {
        const t = timeOf(m);
        return t !== null && t >= cutoff;
      });
    }
    default:
      return out;
  }
}

// ---- Trends ----------------------------------------------------------------------------------------------------------

export const WIN_WINDOW = 10; // win rate = wins in the previous 10 games (one game alone is never shown as a rate)
export const STAT_WINDOW = 5; // KDA / rating = average over the previous 5 games
export const MIN_TREND_POINTS = 2;

export interface TrendPoint {
  /** 1-based position in the chronological list. */
  index: number;
  playedAt: string;
  value: number;
  /** Games inside the rolling window behind this point. */
  n: number;
}

export function rolling(chrono: MatchRecord[], window: number, metric: (w: MatchRecord[]) => number): TrendPoint[] {
  const pts: TrendPoint[] = [];
  for (let i = window - 1; i < chrono.length; i++) {
    const w = chrono.slice(i - window + 1, i + 1);
    pts.push({ index: i + 1, playedAt: chrono[i].playedAt, value: metric(w), n: window });
  }
  return pts;
}

export interface Trends {
  games: number;
  winRate: TrendPoint[];
  kda: TrendPoint[];
  rating: TrendPoint[];
}

export function trends(filtered: MatchRecord[]): Trends {
  const chrono = newestFirst(filtered).reverse();
  return {
    games: chrono.length,
    winRate: rolling(chrono, WIN_WINDOW, (w) => w.filter((m) => m.result === "victory").length / w.length),
    kda: rolling(chrono, STAT_WINDOW, (w) => summarize(w)?.kda ?? 0),
    rating: rolling(chrono, STAT_WINDOW, (w) => summarize(w)?.avgRating ?? 0),
  };
}

// ---- Recent vs previous ----------------------------------------------------------------------------------------------

export const COMPARE_SIZE = 10;

export interface Delta {
  current: number;
  previous: number;
  diff: number;
  /** Relative change in %, null when the previous value is 0 (no meaningful percentage). */
  pct: number | null;
}

const delta = (current: number, previous: number): Delta => ({
  current,
  previous,
  diff: current - previous,
  pct: previous === 0 ? null : ((current - previous) / Math.abs(previous)) * 100,
});

export interface Comparison {
  size: number;
  recent: Summary;
  previous: Summary;
  recentRange: [string, string]; // oldest .. newest playedAt
  previousRange: [string, string];
  winRate: Delta; // values are 0-1; diff*100 = percentage points
  kda: Delta;
  deaths: Delta;
  gold: Delta;
  rating: Delta;
}

/** Latest `size` matches vs the `size` before them. `filtered` carries the active filters, so both periods share them. */
export function compare(filtered: MatchRecord[], size: number = COMPARE_SIZE): Comparison | null {
  const ms = newestFirst(filtered);
  if (ms.length < size * 2) return null;
  const r = ms.slice(0, size);
  const p = ms.slice(size, size * 2);
  const rs = summarize(r);
  const ps = summarize(p);
  if (!rs || !ps) return null;
  return {
    size,
    recent: rs,
    previous: ps,
    recentRange: [r[r.length - 1].playedAt, r[0].playedAt],
    previousRange: [p[p.length - 1].playedAt, p[0].playedAt],
    winRate: delta(rs.winRate, ps.winRate),
    kda: delta(rs.kda, ps.kda),
    deaths: delta(rs.avgDeaths, ps.avgDeaths),
    gold: delta(rs.avgGold, ps.avgGold),
    rating: delta(rs.avgRating, ps.avgRating),
  };
}

// ---- Heroes ----------------------------------------------------------------------------------------------------------

export type HeroSort = "games" | "winRate" | "kda";

/** For win rate / KDA sorts, heroes under MIN_HERO_GAMES go last so 1-2 lucky games never top the table. */
export function sortHeroes(lines: HeroLine[], sort: HeroSort): HeroLine[] {
  return [...lines].sort((a, b) => {
    if (sort === "games") return b.games - a.games || b.winRate - a.winRate;
    const ea = a.games >= MIN_HERO_GAMES ? 0 : 1;
    const eb = b.games >= MIN_HERO_GAMES ? 0 : 1;
    if (ea !== eb) return ea - eb;
    return sort === "winRate" ? b.winRate - a.winRate || b.games - a.games : b.kda - a.kda || b.games - a.games;
  });
}

/** Options for the hero filter, built from ALL loaded matches so choosing a hero never removes the other options. */
export const heroOptions = (all: MatchRecord[]) => byHero(all);
